  validate_adr: {"args": ["validate", "adr/ad-2026-01-15-use-re2-patterns", "--format", "json"], "exit": 0, "stdout": "{\"count\": 1, \"errors\": [], \"gaps\": [], \"body\": {\"words\": 0, \"sections\": [{\"heading\": \"Context\", \"words\": 0}, {\"heading\": \"Alternatives\", \"words\": 0}, {\"heading\": \"Decision\", \"words\": 0}, {\"heading\": \"Consequences\", \"words\": 0}, {\"heading\": \"Prevents\", \"words\": 0}]}, \"lenses\": [{\"code\": \"alternatives\", \"name\": \"A real alternative, not a strawman\", \"section\": null, \"instruction\": \"A decision with one option on the table is a description, not a decision. Name\\nwhat else was genuinely considered and what it would have cost. If there was only\\never one option, say that and say why \\u2014 that is a constraint, and it belongs in\\nContext.\"}, {\"code\": \"consequences\", \"name\": \"The cost, not only the benefit\", \"section\": null, \"instruction\": \"Consequences that are all upside means the tradeoff has not been found yet. What\\ngot harder? What can no longer be done cheaply? A reader six months from now is\\nhere because something is painful and they want to know whether this record\\npredicted it.\"}, {\"code\": \"reversal\", \"name\": \"What would reverse this\", \"section\": null, \"instruction\": \"Name the observation that would make this the wrong call. Without it, nobody\\nknows when to open a superseding record \\u2014 and `supersedes` is the edge that makes\\nthe history readable.\"}, {\"code\": \"rule\", \"name\": \"A rule needs a requirement\", \"section\": null, \"instruction\": \"If this decision creates something the system must always or never do, that is a\\n`requirement`, not a paragraph here. Add it and link it \\u2014 `affects` carries the\\nblast radius, and a rule buried in an ADR body is a rule nothing can check.\"}]}", "stderr": ""},
