  validate_requirement_dangling: {"args": ["validate", "requirement/req-search-answers-within-300-ms", "--format", "json"], "exit": 1, "stdout": "{\"count\": 1, \"errors\": [{\"id\": \"requirement/req-search-answers-within-300-ms\", \"type\": \"requirement\", \"slug\": \"req-search-answers-within-300-ms\", \"field\": \"realized_in\", \"reason\": \"no component 'cmp-serach' to satisfy relation 'realized_in'\"}], \"gaps\": [], \"body\": {\"words\": 0, \"sections\": []}, \"lenses\": [{\"code\": \"single\", \"name\": \"One statement\", \"section\": null, \"instruction\": \"Does the body state exactly one thing? An \\\"and\\\", a bulleted list of behaviours, or\\ntwo sentences each with their own verb mean this is two requirements. Split it \\u2014\\ntwo records each with their own `realized_in` are worth more than one that cannot\\nbe satisfied or violated as a unit.\"}, {\"code\": \"testable\", \"name\": \"Observable from outside\", \"section\": null, \"instruction\": \"Could someone who did not write this tell whether the system satisfies it, without\\nreading the implementation? If the only way to check is to open the code, this is\\ndescribing a design, not stating a requirement.\"}, {\"code\": \"measurable\", \"name\": \"A number and its measurement\", \"section\": null, \"instruction\": \"Look for the value, the unit, where it is measured, over what window, and what\\nenforces it. Flag \\\"gracefully\\\", \\\"robust\\\", \\\"scalable\\\", \\\"efficient\\\", \\\"fast\\\",\\n\\\"user-friendly\\\" \\u2014 an adjective is not a bound. \\\"p99 under 200 ms at the API edge,\\nmeasured over a rolling hour, alerted on in the latency dashboard\\\" is.\"}, {\"code\": \"realized\", \"name\": \"Where it is satisfied\", \"section\": null, \"instruction\": \"`realized_in` is the only edge tying a rule to the code that satisfies it, and a\\nrequirement without one is unfinished by design. If no component satisfies it yet,\\nthat is the honest answer and the gap is the point \\u2014 but check that it is not\\nsimply unlinked. If a use case depends on this rule, name it in `use_cases`: a\\nrule no flow needs is either global or unowned, and the graph should say which.\"}]}", "stderr": ""},
